#!/usr/bin/env bash
# Run from the lean-ch repository root.
set -euo pipefail
export PATH="$HOME/.elan/bin:$PATH"

replay_capstone() {
  local base="${CH_FRONTIER_DIR:-.lake/ch-frontier}"
  mkdir -p "$base"
  local receipt
  receipt=$(mktemp -d "$base/replay.XXXXXXXX")
  local log="$receipt/Capstone.log"
  local status=0
  CH_CATALOG_TRACE_FILE="${CH_CATALOG_TRACE_FILE:-$receipt/catalog.trace}" \
    lake env lean checkpoints/shen_extension/Capstone.lean 2>&1 | tee "$log" || status=$?
  if ((status != 0)); then
    if python checkpoints/shen_extension/report_family_frontier.py "$log" > "$receipt/frontier.tmp"; then
      mv "$receipt/frontier.tmp" "$receipt/frontier.json"
      echo "Exact open contexts indexed in $receipt/frontier.json"
    else
      rm -f -- "$receipt/frontier.tmp"
      echo "Check the Lean diagnostics in $log" >&2
    fi
  fi
  echo "Lean replay log in $log"
  return "$status"
}

if [[ ${1:-} == --replay ]]; then
  replay_capstone
  exit
fi

# Compile one checkpoint file to its .olean unless it is already up to date.
# module_keys.py gives each file a key over its source, its project imports,
# the toolchain and the manifest; the key of the last good compile is kept
# beside the .olean. An unchanged key means the same inputs, so the file is
# skipped. Set CH_REBUILD=1 to compile everything.
declare -A ch_key=()
while read -r key_path key_value; do
  ch_key[$key_path]=$key_value
done < <(python checkpoints/shen_extension/module_keys.py | tr -d '\r')
compiled=0
skipped=0
compile() {
  local src=$1
  local out=".lake/build/lib/lean/${src%.lean}.olean"
  local key=${ch_key[$src]:-}
  if [[ -z $key ]]; then
    echo "No content key for $src" >&2
    return 1
  fi
  if [[ -z ${CH_REBUILD:-} && -f $out && -f $out.key && $(<"$out.key") == "$key" ]]; then
    skipped=$((skipped + 1))
    return 0
  fi
  rm -f -- "$out.key"
  mkdir -p "$(dirname "$out")"
  lake env lean -o "$out" "$src"
  printf '%s' "$key" > "$out.key"
  compiled=$((compiled + 1))
}

